  "settings.forgeorbit_looks_up_the_token_stored_for_6841b6": "ForgeOrbit looks up the token stored for the repo's remote host (the raw ssh host — e.g. github-work.com for an ssh alias remote). If none is stored for that exact host, it falls back to whatever token is stored under the github.com entry.",
  "settings.if_no_token_is_stored_for_the_a51533": "If no token is stored for the host, ForgeOrbit reads the GITHUB_TOKEN or GH_TOKEN environment variable from the process it was launched with.",
  "settings.if_neither_of_the_above_resolves_a_7d2a8a": "If neither of the above resolves a token, ForgeOrbit shells out to `gh auth token` and uses whatever the GitHub CLI has you logged in as, if anything.",
  "settings.pull_requests_issues_comments_reviews_labels_milestones_fa1f5e": "Pull requests, issues, comments, reviews, labels, milestones, releases, commit statuses, check runs, diffs, and repository Discussions.",
  "settings.github_actions_re_running_cancelling_and_dispatching_e98414": "GitHub Actions — re-running, cancelling, and dispatching workflows, and pushing any changes to workflow files.",
  "settings.the_repo_s_notifications_inbox_and_thread_6f959a": "The repo's notifications inbox and thread subscribe/unsubscribe. This API only accepts classic tokens — a fine-grained token cannot reach it.",
  "settings.listing_creating_merging_closing_drafting_and_auto_90149a": "Listing, creating, merging, closing, drafting, and auto-merging PRs; reviews, line comments, suggestions, and review threads.",
  "settings.pick_a_name_and_expiration_set_resource_62fbbe": "Pick a name and expiration. Set \"Resource owner\" to your personal account, or the organization that owns the repositories you want ForgeOrbit to work with.",
  "settings.choose_only_select_repositories_and_pick_the_f643aa": "Choose \"Only select repositories\" and pick the repos ForgeOrbit should touch (or \"All repositories\" if you want it to cover everything under that owner).",
  "settings.if_the_token_needs_to_reach_an_618f64": "If the token needs to reach an org with SAML SSO enabled, open the token's \"Configure SSO\" menu afterward and authorize it for that organization.",
  "settings.mergeability_hasn_t_been_verified_merging_will_efe247": "Mergeability hasn't been verified — merging will be attempted as-is",
  "settings.ready_to_merge_28f738": "Ready to merge",
  "settings.mergeable_some_checks_are_pending_or_failing_6d5a67": "Mergeable — some checks are pending or failing",
  "settings.out_of_date_with_the_base_branch_066527": "Out of date with the base branch",
  "settings.conflicts_must_be_resolved_before_merging_e71d55": "Conflicts must be resolved before merging",
  "settings.blocked_by_required_reviews_or_checks_256f24": "Blocked by required reviews or checks",
  "settings.draft_mark_ready_for_review_to_merge_b2c139": "Draft — mark ready for review to merge",
  "settings.wait_for_the_import_to_finish_then_7f2dfb": "Wait for the import to finish, then drop the file again.",
  "settings.under_api_tokens_click_create_api_token_921140": "Under \"API tokens\", click \"Create API token with scopes\" (NOT the plain, scopeless \"Create API token\" — a scopeless token works for Jira/Confluence but api.bitbucket.org rejects it). Give it a name, then select \"Bitbucket\" and tick the scopes listed below.",
  "settings.back_in_the_git_host_tokens_section_91fba9": "Back in the Git host tokens section, enter the host (bitbucket.org, or your ssh alias host) and put your Atlassian account email, a colon, then the API token in the token field — e.g. \"jane@example.com:ATATT3x…\". Bitbucket app passwords were retired on 2026-06-09; replace any saved app password with a token in this format.",
  "settings.listing_repos_reading_diffs_commit_statuses_and_edc5b7": "Listing repos, reading diffs/commit statuses, and merging pull requests.",
  "settings.listing_creating_merging_declining_and_reviewing_prs_80e6a6": "Listing, creating, merging, declining, and reviewing PRs; PR and line comments; merge-conflict detection.",
  "settings.the_repository_issue_tracker_listing_creating_updating_5184d8": "The repository issue tracker — listing, creating, updating, and commenting.",
  "settings.resolving_the_signed_in_account_used_for_9fb471": "Resolving the signed-in account, used for \"assigned to me\"/\"created by me\" filters.",
  "settings.from_your_gitlab_avatar_go_to_edit_b86358": "From your GitLab avatar, go to \"Edit profile\", then \"Access tokens\" in the left sidebar.",
  "settings.click_create_personal_access_token_and_copy_a9a905": "Click \"Create personal access token\" and copy it — it's shown only once. Back in the Git host tokens section, enter the host (gitlab.com, or your ssh alias host) and the token itself.",
  "settings.the_prompt_will_be_removed_permanently_9e2396": "The prompt will be removed permanently.",
